import initSqlJs from 'sql.js'
import sqlWasmUrl from 'sql.js/dist/sql-wasm.wasm?url'

// Only entry point the app should use to read game data.
// Backed by a prebuilt SQLite file (public/data/empire-connect.sqlite,
// generated by `npm run import-data`) loaded client-side via sql.js.
let dbPromise = null

function getDb() {
  if (!dbPromise) {
    dbPromise = (async () => {
      const SQL = await initSqlJs({ locateFile: () => sqlWasmUrl })
      const buf = await fetch(`${import.meta.env.BASE_URL}data/empire-connect.sqlite`).then((r) => r.arrayBuffer())
      return new SQL.Database(new Uint8Array(buf))
    })()
  }
  return dbPromise
}

function all(db, sql, params = []) {
  const stmt = db.prepare(sql)
  stmt.bind(params)
  const rows = []
  while (stmt.step()) rows.push(stmt.getAsObject())
  stmt.free()
  return rows
}

function groupBy(rows, key) {
  const out = {}
  for (const row of rows) {
    ;(out[row[key]] ??= []).push(row)
  }
  return out
}

export async function getCities() {
  const db = await getDb()
  const cities = all(db, 'SELECT id, lat, lon, founded_year AS foundedYear, dissolved_year AS dissolvedYear FROM city')
  const names = all(
    db,
    'SELECT city_id AS cityId, name, start_year AS startYear, end_year AS endYear FROM city_name ORDER BY city_id, start_year',
  )
  const namesByCity = groupBy(names, 'cityId')

  return cities.map((c) => {
    const cityNames = namesByCity[c.id] ?? []
    const currentName = cityNames.find((n) => n.endYear == null) ?? cityNames[cityNames.length - 1]
    return { ...c, name: currentName?.name ?? c.id, names: cityNames }
  })
}

export async function getHoldings() {
  const db = await getDb()
  const rows = all(
    db,
    `SELECT h.city_id AS city, e.id AS empireId, e.name AS nation, h.start_year AS start, h.end_year AS end, h.synthetic AS synthetic
     FROM holding h JOIN empire e ON e.id = h.empire_id`,
  )
  return rows.map((r) => ({ ...r, synthetic: !!r.synthetic }))
}

export async function getEmpires() {
  const db = await getDb()
  return all(db, 'SELECT id, name, color FROM empire')
}

// Name a city was known by at a given year (falls back to the current/most recent name).
export function nameAtYear(city, year) {
  const match = city.names.find((n) => n.startYear <= year && (n.endYear == null || year <= n.endYear))
  return match?.name ?? city.name
}

export async function getBorderEras() {
  const db = await getDb()
  return all(db, 'SELECT id, era_year AS eraYear, file FROM border_era ORDER BY era_year')
}

export async function getBorderEmpireMap(borderEraId) {
  const db = await getDb()
  return all(
    db,
    `SELECT bem.feature_name AS featureName, e.id AS empireId, e.color AS color
     FROM border_empire_map bem JOIN empire e ON e.id = bem.empire_id
     WHERE bem.border_era_id = ?`,
    [borderEraId],
  )
}
